@mcp.tool()
def fix(prompt: str) -> dict:
    """Fix design to address breachs by invoking the fixer subagent.
    [🔬coda📚py💻coda🔖tools🛠️fix](semiorepo://p/r/coda/b/l/py/f/coda.py/s/Tools/d/i/fix)
    """
    proj = _get_project_config()
    if not proj:
